import json,sys,importlib.util
from pathlib import Path
sys.dont_write_bytecode=True
R=Path(__file__).resolve().parent
load=lambda n:json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2)+'\n')
# Preserve the complete independently rerun negative counterexample, including original metadata.
p=R/'author-check/old-bank/workspace/17592186229183.py';spec=importlib.util.spec_from_file_location('old_radius',p);g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
r=g.generate('easy',seed=41072,template='q-336506',parameters={'H':'20','v':'10','q':'1','c':'0.4','rin':'6','rout':'4'});assert r['question'][':question/id']==load('negative-shortcut-results.json')['minimal']['question_id'];save('negative-radius-records.json',[r])
a=load('source-analysis.json')
source={k:a[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']}
def passed(paths,details):return {'status':'passed','evidence_paths':paths,'details':details}
checks={
'source_replay':passed(['source-analysis.json','source-replay-results.json','source-replay-records.json','repair-verification.json','independent-negative-controls.json'],'All eleven supplied observed profiles replay full banks, prompts, solutions, keys and omissions. Missing q-336499 evidence and source editorial corrections are documented. Historical failing controls reproduce retained defects.'),
'math':passed(['math-results.json','displayed-math-results.json','counterfactual-results.json','decision-results.json'],'Prompt-derived exact mass balance, ODE and initial-condition residuals agree for 54 records; 21 displayed solved expressions and endpoints checked independently. Controlled relevant changes recompute the expected mass.'),
'variety':passed(['sample-records.json','sampling-summary.json','decision-results.json','delivery-selection-results.json'],'Fresh 44-record sample covers eleven contexts and 34 distinct physical tasks. All five correct ranks remain eligible, including a low-mass boundary. Exact batch: ranks 2/3, position 3 correct on 4/5; no tested strategy solves every batch item. Actual delivery preserves all 44 sample and five batch records.'),
'scope':passed(['source-analysis.json','scope-results.json','render-inspection.json'],'Requested easy variants preserve source mass-balance modeling, quadratic integrating factor, initial condition, overflow-time operation and five-choice numerical response. Unchanged moderate/hard extensions are outside this targeted certification.'),
'grading':passed(['grader-input.json','grader-report.json','same-bank-records.json'],'Actual native learner grader: 36 expected acceptances, 144 expected rejections, zero unresolved cases. Every displayed choice tested for delivered, controlled-dependency, same-bank and low-boundary cases; radio response contract requires no free-entry equivalence test.'),
'rendering':passed(['render/rendering.json','render-records.json','render-inspection.json','render-inspection/remaining-top.png','render-inspection/case-01-middle.png'],'Unmodified UI renders all 27 records without reported math, image, font or JavaScript errors. Screenshots inspected across complete batch, all eleven contexts, relevant/irrelevant pairs and five same-bank keys.'),
'packaging':passed(['packaging-results.json','runtime-results.json','package-before.json','package-after.json','relocation-records.json'],'Python 3.13.5 and SymPy 1.14.0 exactly match nested dependency declarations. Deterministic replay and manifest-only relocation pass; physical rejection tested. All 213 original package files remain byte-for-byte unchanged.'),
'decision_variation':passed(['pedagogical-variation.json','decision_checks.py','decision-results.json','same-bank-records.json','delivery-controls/accepted.json','grader-report.json','independent-negative-controls.json','negative-radius-records.json','affected-inventory.json','generated-records.json','inventory-results.json'],'Original median, missing-source and radius counterexamples are reproduced with historical controls and pass current regressions. Identical visible bank supports five physically computed keys; conditional template and geometry probes no longer imply a correct key. Actual delivery and conditional native selection examined against captured basis 5395. Ten old generated inventory items retain the historical median defect; they are reverified separately and are not current outputs.')}
result={'verdict':'accepted','summary':'Current easy generator and exact five-item batch pass all eight checks; retained shortcuts are repaired. Ten historical inventory defects remain documented separately. Package unchanged.','source_analysis':source,'checks':checks,'findings':[]}
for check in checks.values():
 for p in check['evidence_paths']:assert (R/p).is_file() and (R/p).stat().st_size>0,p
save('result.json',result)
save('review-result.json',result)
(R/'session-state.md').write_text('Completed: accepted current easy generator and exact five-item batch. Independent source analysis confirmed; all retained findings inspected and reproduced with failing historical controls, then current regressions rerun. 44 fresh records / 34 physical tasks, eleven complete observed banks, 54 exact math checks, 21 displayed-solution checks, 36 native accepted and 144 rejected responses, and 27 actual UI previews passed. Actual delivery accepts 44 sample + 5 batch + 5 same-bank controls; conditional native selection examined against basis 5395. Ten historical inventory median defects reverified in affected-inventory.json / generated-records.json, separate from current construction. All 213 package files unchanged. Final result: result.json. No database, publication or package edits.\n')
print(json.dumps({'verdict':result['verdict'],'checks':list(checks),'evidence_paths_verified':True}))
